const crypto = require('crypto');

function stripAccents(s) {
  return (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

const results = [];

for (const item of $input.all()) {
  const body = item.json.body || item.json;

  // envelope (JSON en texto)
  let envelope = {};
  try {
    envelope = typeof body.envelope === 'string' ? JSON.parse(body.envelope) : (body.envelope || {});
  } catch (e) {
    envelope = {};
  }

  // reply_to: primera direccion que empiece con "r+", si no la primera de la lista
  const toList = Array.isArray(envelope.to) ? envelope.to : (envelope.to ? [envelope.to] : []);
  let reply_to = '';
  const rPlus = toList.find(a => typeof a === 'string' && a.toLowerCase().startsWith('r+'));
  if (rPlus) {
    reply_to = rPlus;
  } else if (toList.length > 0) {
    reply_to = toList[0];
  }

  // remitente
  const remitente = envelope.from || body.from || '';

  // asunto
  const asunto = body.subject || '';

  // headers (texto plano, respetando encabezados partidos en varias lineas)
  const rawHeaders = body.headers || '';
  const unfolded = rawHeaders.replace(/\r?\n[ \t]+/g, ' ');
  const headerLines = unfolded.split(/\r?\n/);
  const headers = {};
  for (const line of headerLines) {
    const idx = line.indexOf(':');
    if (idx === -1) continue;
    const name = line.slice(0, idx).trim().toLowerCase();
    const value = line.slice(idx + 1).trim();
    if (!(name in headers)) headers[name] = value;
  }

  const messageId = headers['message-id'] || '';
  const autoSubmitted = headers['auto-submitted'];
  const xAutoreply = headers['x-autoreply'];
  const xAutorespond = headers['x-autorespond'];
  const xAutoResponseSuppress = headers['x-auto-response-suppress'];
  const precedence = headers['precedence'];

  // automatica
  let automatica = false;
  if (autoSubmitted !== undefined && autoSubmitted.toLowerCase() !== 'no') automatica = true;
  if (xAutoreply !== undefined || xAutorespond !== undefined) automatica = true;
  if (xAutoResponseSuppress !== undefined) automatica = true;
  if (precedence !== undefined && precedence.toLowerCase() === 'auto_reply') automatica = true;

  const asuntoNorm = stripAccents(asunto).toLowerCase().trim();
  const prefijos = [
    'respuesta automatica',
    'fuera de la oficina',
    'fuera de oficina',
    'out of office',
    'automatic reply',
    'autoreply',
  ];
  if (prefijos.some(p => asuntoNorm.startsWith(p))) automatica = true;

  // contenido: text; si vacio, html sin etiquetas
  let contenido = body.text || '';
  if (!contenido || !contenido.trim()) {
    const html = body.html || '';
    contenido = html.replace(/<[^>]*>/g, '');
  }

  // quitar la parte citada del correo original
  const cutCandidates = [];

  // atribución (Gmail puede partirla en varios renglones, hasta 2 saltos de línea)
  const attrMatch = /^(On |El )(?:[^\n]*\n){0,2}[^\n]*?(wrote:|escribió:)/m.exec(contenido);
  if (attrMatch) cutCandidates.push(attrMatch.index);

  // -----Original Message-----
  const origMatch = /^[ \t]*-----Original Message-----[ \t]*$/m.exec(contenido);
  if (origMatch) cutCandidates.push(origMatch.index);

  // líneas citadas que empiezan con ">"
  const quoteMatch = /^[ \t]*>/m.exec(contenido);
  if (quoteMatch) cutCandidates.push(quoteMatch.index);

  if (cutCandidates.length > 0) {
    contenido = contenido.slice(0, Math.min(...cutCandidates));
  }
  contenido = contenido.trim().slice(0, 8000);

  // execution_id
  let execution_id;
  if (messageId) {
    execution_id = 'msg-' + crypto.createHash('sha256').update(messageId).digest('hex').slice(0, 40);
  } else {
    execution_id = 'msg-' + crypto.createHash('sha256').update(remitente + asunto + contenido).digest('hex').slice(0, 40);
  }

  // message_id: encabezado Message-ID tal cual (sin hash), sin espacios extremos, max 255; null si no viene
  const rawMessageId = headers['message-id'];
  const messageIdTrim = typeof rawMessageId === 'string' ? rawMessageId.trim() : '';
  const message_id = messageIdTrim ? messageIdTrim.slice(0, 255) : null;

  // asunto de salida: subject recortado a 500; null si no viene
  const rawSubject = body.subject;
  const asuntoSalida = (rawSubject === undefined || rawSubject === null || String(rawSubject) === '')
    ? null
    : String(rawSubject).slice(0, 500);

  results.push({
    json: { execution_id, reply_to, remitente, asunto: asuntoSalida, contenido, automatica, message_id },
  });
}

return results;

const r = $('Leer respuesta').first().json;
const api = $('Registrar respuesta').first().json;
const DESTINOS = ["<CORREO_ADMIN_1>", "<CORREO_DIRECCION>", "<CORREO_ADMIN_2>"];
const contactoNombre = String(api.contacto_nombre ?? "").trim();
const empresaNombre = String(api.empresa_nombre ?? "").trim();
const prospectoId = api.prospecto_id ?? "no identificado";
const partesContacto = [contactoNombre ? "Contacto: " + contactoNombre : null, empresaNombre ? "Empresa: " + empresaNombre : null].filter(Boolean);
const lineaProspecto = partesContacto.length ? partesContacto.join(" · ") + " (prospecto " + prospectoId + ")" : "Prospecto: " + prospectoId;
const extras = [api.tardia ? "respuesta tardía" : null, api.identificada ? null : "NO identificada"].filter(Boolean);
const texto = [
  "Llegó una respuesta de un prospecto" + (extras.length ? " (" + extras.join(", ") + ")" : "") + ".",
  "De: " + (r.remitente || "?"),
  "Asunto: " + (r.asunto || "(sin asunto)"),
  lineaProspecto,
  "",
  (r.contenido || "(vacía)").slice(0, 500),
  "",
  "Clasifícala en el CRM: https://crm-prospeccion-outbound.web.app/tareas (Cola de clasificación)"
].join("\n");
return [{ json: { sendgrid: {
  personalizations: [{ to: DESTINOS.map((email) => ({ email })) }],
  from: { email: "hola@contacto.nano-bridge-mex.com", name: "NANOBRIDGE alertas" },
  subject: "[NANOBRIDGE] Respondió " + (r.remitente || "un prospecto") + (extras.length ? " (" + extras.join(", ") + ")" : ""),
  content: [{ type: "text/plain", value: texto }],
  tracking_settings: { subscription_tracking: { enable: false }, click_tracking: { enable: false, enable_text: false }, open_tracking: { enable: false } },
  mail_settings: { sandbox_mode: { enable: false } }
} } }];

// ============================================================
// PT2 · "Datos para IA"  (pegar completo en el nodo Code, después de
// "Responder 200"). Junta lo que necesita el subflujo PT2a. La decisión
// de si se manda o no a Gemini la toma PT2a, no este nodo.
// ============================================================
const r = $('Leer respuesta').first().json;
const api = $('Registrar respuesta').first().json;

return [{
  json: {
    remitente: r.remitente,
    contenido: r.contenido,
    automatica: r.automatica === true,
    respuesta_id: api.id ?? null,
    tarea_id: api.tarea_id ?? null,
    identificada: api.identificada === true,
    ya_existia: api.ya_existia === true,
    contacto_nombre: api.contacto_nombre ?? null,
    empresa_nombre: api.empresa_nombre ?? null
  }
}];
